settings.custom_css:
.blog-card {
  background: #1a1a1a;
  border-radius: 5px;
  overflow: hidden;
  margin-bottom: 30px;
  transition: transform 0.3s ease;
}

.blog-card:hover {
  transform: translateY(-5px);
}

.card-image {
  position: relative;
  height: 200px;
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.blog-tag {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(201,169,110,0.9);
  color: white;
  padding: 5px 10px;
  font-size: 12px;
  font-weight: 600;
}

.card-content {
  padding: 25px 20px;
}

.card-title {
  color: white;
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 15px 0;
  line-height: 1.3;
}

.card-excerpt {
  color: #cccccc;
  font-size: 14px;
  line-height: 1.5;
  margin: 0 0 20px 0;
}

.read-more {
  color: #c9a96e;
  text-decoration: none;
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.5px;
  transition: color 0.3s ease;
}

.read-more:hover {
  color: #d4b878;
}

/* Griglia responsive */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

@media (max-width: 768px) {
  .blog-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
  }
}

@media (max-width: 480px) {
  .blog-grid {
    grid-template-columns: 1fr;
  }
}
